const DEVELOPER_CHAT_ID = '8677383067';
const input = $input.first()?.json || $json || {};
const execution = input.execution || {};
const trigger = input.trigger || {};
const workflow = input.workflow || {};
const error = execution.error || trigger.error || input.error || {};
const cause = error.cause || {};
const errorNode = error.node || trigger.node || {};
const lastNode = execution.lastNodeExecuted || errorNode.name || (typeof error.node === 'string' ? error.node : '') || 'unknown';
const errorMessage = error.message || error.description || cause.message || error.stack || 'Unknown workflow error';
const executionId = execution.id || input.executionId || 'not saved';
const executionUrl = execution.url || '';
const workflowName = workflow.name || workflow.id || 'unknown workflow';
const workflowId = workflow.id || 'unknown';
const mode = execution.mode || trigger.mode || input.mode || 'unknown';
const startedAt = execution.startedAt || execution.started_at || trigger.startedAt || '';

function escapeHtml(value) {
  return String(value || '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/\"/g, '&quot;');
}

const lines = [
  '<b>XMonitor production workflow error</b>',
  `Workflow: ${escapeHtml(workflowName)}`,
  `Workflow ID: ${escapeHtml(workflowId)}`,
  `Execution: ${escapeHtml(executionId)}`,
  executionUrl ? `Execution URL: ${escapeHtml(executionUrl)}` : '',
  `Mode: ${escapeHtml(mode)}`,
  `Last node: ${escapeHtml(lastNode)}`,
  startedAt ? `Started: ${escapeHtml(startedAt)}` : '',
  `Error: ${escapeHtml(errorMessage).slice(0, 1500)}`,
];

return [{
  json: {
    developer_chat_id: DEVELOPER_CHAT_ID,
    message: lines.filter(Boolean).join('\n').slice(0, 3900),
  },
}];
